-- OFFLINE-PREPARED ONLY; no company query executed.
-- Use already authorized SELECT role and warehouse; run Q00 first, Q01 before joins.
-- Local definitions: sql/02,03,12,16,18,19. Standard constraints are not enforcement evidence.
-- Large-table scans are intentional health diagnostics; execute one labelled query at a time.

-- Q00 identity
-- Non-empty result: context only; STOP unless the company identity matches. Current database must be EFNS_DEV. No session context changes are made.
SELECT CURRENT_ORGANIZATION_NAME() AS ORGANIZATION, CURRENT_ACCOUNT_NAME() AS ACCOUNT_NAME, CURRENT_ACCOUNT() AS ACCOUNT_LOCATOR, CURRENT_REGION() AS REGION, CURRENT_DATABASE() AS SESSION_DATABASE, CURRENT_ROLE() AS ROLE_NAME, 'QDCTNKN / UW19058 / CB12755 / AWS_CA_CENTRAL_1 / EFNS_DEV' AS EXPECTED_SCOPE;

-- Q01 duplicate primary IDs - every declared CORE table
-- Non-empty result: duplicate case-insensitive, trimmed identity. Check before any joined diagnostic; declared keys alone do not enforce uniqueness.
SELECT 'ACCOUNT' AS TABLE_NAME, NULLIF(UPPER(TRIM(TO_VARCHAR(ACCOUNT_ID))), '') AS NORMALIZED_ID, COUNT(*) AS RECORDS FROM EFNS_DEV.CORE.ACCOUNT GROUP BY NULLIF(UPPER(TRIM(TO_VARCHAR(ACCOUNT_ID))), '') HAVING COUNT(*)>1
UNION ALL
SELECT 'CONTACT' AS TABLE_NAME, NULLIF(UPPER(TRIM(TO_VARCHAR(CONTACT_ID))), '') AS NORMALIZED_ID, COUNT(*) AS RECORDS FROM EFNS_DEV.CORE.CONTACT GROUP BY NULLIF(UPPER(TRIM(TO_VARCHAR(CONTACT_ID))), '') HAVING COUNT(*)>1
