-- Q02 orphan references
-- Non-empty result: nonempty reference has no parent. Optional NULL is allowed; text NULL remains an unresolved reference. NOT EXISTS avoids duplicate-parent fanout. Checking a semantic link does not declare a new FK.
SELECT 'FLOCK.ACCOUNT_ID -> ACCOUNT.ACCOUNT_ID' AS RELATIONSHIP, TO_VARCHAR(c.FLOCK_ID) AS RECORD_ID, TO_VARCHAR(c.ACCOUNT_ID) AS REFERENCE_ID FROM EFNS_DEV.CORE.FLOCK c WHERE NULLIF(UPPER(TRIM(TO_VARCHAR(c.ACCOUNT_ID))), '') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM EFNS_DEV.CORE.ACCOUNT p WHERE NULLIF(UPPER(TRIM(TO_VARCHAR(p.ACCOUNT_ID))), '')=NULLIF(UPPER(TRIM(TO_VARCHAR(c.ACCOUNT_ID))), ''))
UNION ALL
