SELECT 'FLOCK_EVENT.FLOCK_ID -> FLOCK.FLOCK_ID' AS RELATIONSHIP, TO_VARCHAR(c.EVENT_ID) AS RECORD_ID, TO_VARCHAR(c.FLOCK_ID) AS REFERENCE_ID FROM EFNS_DEV.CORE.FLOCK_EVENT c WHERE NULLIF(UPPER(TRIM(TO_VARCHAR(c.FLOCK_ID))), '') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM EFNS_DEV.CORE.FLOCK p WHERE NULLIF(UPPER(TRIM(TO_VARCHAR(p.FLOCK_ID))), '')=NULLIF(UPPER(TRIM(TO_VARCHAR(c.FLOCK_ID))), ''))
