SELECT 'ACCOUNT.GRADING_STATION_ACCOUNT_ID -> ACCOUNT.ACCOUNT_ID' AS RELATIONSHIP, TO_VARCHAR(c.ACCOUNT_ID) AS RECORD_ID, TO_VARCHAR(c.GRADING_STATION_ACCOUNT_ID) AS REFERENCE_ID FROM EFNS_DEV.CORE.ACCOUNT c WHERE NULLIF(UPPER(TRIM(TO_VARCHAR(c.GRADING_STATION_ACCOUNT_ID))), '') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM EFNS_DEV.CORE.ACCOUNT p WHERE NULLIF(UPPER(TRIM(TO_VARCHAR(p.ACCOUNT_ID))), '')=NULLIF(UPPER(TRIM(TO_VARCHAR(c.GRADING_STATION_ACCOUNT_ID))), ''))
