-- Q04 multiple Delivery rows
-- Non-empty result: possible duplicate or legitimate multiple Delivery: inspect source GUIDs. Matching Bird Count is only a clue, not a stock formula. Run Q01 first.
WITH deliveries AS (
 SELECT NULLIF(UPPER(TRIM(TO_VARCHAR(FLOCK_ID))), '') AS FLOCK_KEY, COUNT(*) AS DELIVERY_ROWS,
 COUNT(DISTINCT NULLIF(UPPER(TRIM(TO_VARCHAR(FLOCK_TRANSACTION_ID))), '')) AS UNIQUE_TRANSACTION_IDS, SUM(QUANTITY) AS KNOWN_DELIVERY_SUM
 FROM EFNS_DEV.CORE.FLOCK_TRANSACTION WHERE UPPER(TRIM(TRANSACTION_TYPE))='DELIVERY'
 GROUP BY NULLIF(UPPER(TRIM(TO_VARCHAR(FLOCK_ID))), '') HAVING COUNT(*)>1
)
SELECT f.FLOCK_ID, f.FLOCK_NUMBER, f.BIRD_COUNT, d.DELIVERY_ROWS, d.UNIQUE_TRANSACTION_IDS,
 d.KNOWN_DELIVERY_SUM, COALESCE(COUNT_IF(t.QUANTITY=f.BIRD_COUNT),0) AS DELIVERIES_EQUAL_BIRD_COUNT
FROM deliveries d JOIN EFNS_DEV.CORE.FLOCK f ON NULLIF(UPPER(TRIM(TO_VARCHAR(f.FLOCK_ID))), '')=d.FLOCK_KEY
JOIN EFNS_DEV.CORE.FLOCK_TRANSACTION t ON NULLIF(UPPER(TRIM(TO_VARCHAR(t.FLOCK_ID))), '')=d.FLOCK_KEY AND UPPER(TRIM(t.TRANSACTION_TYPE))='DELIVERY'
GROUP BY f.FLOCK_ID,f.FLOCK_NUMBER,f.BIRD_COUNT,d.DELIVERY_ROWS,d.UNIQUE_TRANSACTION_IDS,d.KNOWN_DELIVERY_SUM
ORDER BY d.DELIVERY_ROWS DESC;

-- Q05 owner/registration mismatch
-- Non-empty result: Owner differs from registration Account, including missing Owner. Related Account is a different role. Resolve Q01 duplicates first.
SELECT t.QUOTA_TRANSACTION_ID,t.QUOTA_ID,t.OWNER_ACCOUNT_ID,q.ACCOUNT_ID AS REGISTRATION_ACCOUNT_ID FROM EFNS_DEV.CORE.QUOTA_TRANSACTION t JOIN EFNS_DEV.CORE.QUOTA_REGISTRATION q ON NULLIF(UPPER(TRIM(TO_VARCHAR(t.QUOTA_ID))), '')=NULLIF(UPPER(TRIM(TO_VARCHAR(q.QUOTA_ID))), '') WHERE NULLIF(UPPER(TRIM(TO_VARCHAR(t.OWNER_ACCOUNT_ID))), '') IS DISTINCT FROM NULLIF(UPPER(TRIM(TO_VARCHAR(q.ACCOUNT_ID))), '');

