-- Q07 Account names/IDs used in disposal plant or method text
-- Non-empty result: name is a candidate only, not a recovered lookup GUID. Counts are distinct Flocks per field; do not sum field counts into stock.
WITH disposal_text AS (
 SELECT FLOCK_ID,'DISPOSAL_PLANT' AS SOURCE_FIELD,DISPOSAL_PLANT AS STORED_TEXT FROM EFNS_DEV.CORE.FLOCK
 UNION ALL
 SELECT FLOCK_ID,'DISPOSAL_METHOD' AS SOURCE_FIELD,DISPOSAL_METHOD AS STORED_TEXT FROM EFNS_DEV.CORE.FLOCK
)
SELECT a.ACCOUNT_ID,a.ORGANIZATION_NAME,f.SOURCE_FIELD,f.STORED_TEXT,
 CASE WHEN NULLIF(UPPER(TRIM(TO_VARCHAR(f.STORED_TEXT))), '')=NULLIF(UPPER(TRIM(TO_VARCHAR(a.ACCOUNT_ID))), '') THEN 'EXACT_ACCOUNT_ID_TEXT' ELSE 'DISPLAY_NAME_CANDIDATE_ONLY' END AS MATCH_BASIS,
 COUNT(DISTINCT NULLIF(UPPER(TRIM(TO_VARCHAR(f.FLOCK_ID))), '')) AS FLOCKS
FROM disposal_text f JOIN EFNS_DEV.CORE.ACCOUNT a ON NULLIF(UPPER(TRIM(TO_VARCHAR(f.STORED_TEXT))), '')=NULLIF(UPPER(TRIM(TO_VARCHAR(a.ACCOUNT_ID))), '') OR NULLIF(UPPER(TRIM(TO_VARCHAR(f.STORED_TEXT))), '')=NULLIF(UPPER(TRIM(TO_VARCHAR(a.ORGANIZATION_NAME))), '')
WHERE NULLIF(UPPER(TRIM(TO_VARCHAR(f.STORED_TEXT))), '') IS NOT NULL
GROUP BY a.ACCOUNT_ID,a.ORGANIZATION_NAME,f.SOURCE_FIELD,f.STORED_TEXT,MATCH_BASIS;

-- Q08 DEV_TEST prefix candidates
