-- Q09 future/uncovered CORE tables
-- Non-empty result: deployed table outside local reviewed definitions: extend diagnostics after checking metadata. No deployed inventory was queried here.
SELECT TABLE_NAME FROM EFNS_DEV.INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA='CORE' AND TABLE_TYPE='BASE TABLE' AND TABLE_NAME NOT IN ('ACCOUNT', 'CONTACT', 'DIM_EFC_DATE', 'FACILITY', 'FACILITY_DETAIL', 'FARM_LOCATION', 'FLOCK', 'FLOCK_EVENT', 'FLOCK_TRANSACTION', 'PRODUCTION_RECORD', 'PRODUCTION_SIZE_BREAKDOWN', 'QUOTA_ALLOCATION', 'QUOTA_REGISTRATION', 'QUOTA_TRANSACTION', 'SALMONELLA_TEST', 'SALMONELLA_TEST_SAMPLE');
